package dev.unbox.unpvp;
import com.google.gson.*;
import java.io.*;
import java.net.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;
import java.util.zip.ZipFile;
import net.minecraft.client.gui.GuiScreen;
import net.minecraft.client.resources.ResourcePackRepository;

/** Native Unbox browser. Network work is lazy and off-thread; only verified ZIPs enter resourcepacks. */
final class PackBrowser extends UiScreen {
 private static final String API="https://api.modrinth.com/v2/";
 private final ExecutorService worker=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"Unbox pack browser");t.setDaemon(true);return t;});
 Future<List<Pack>> pending;private boolean closed;boolean online;private String query="";String status="";private int page,left,top,pw,ph;
 List<Pack> packs=new ArrayList<>();private List<ResourcePackRepository.Entry> local=new ArrayList<>();
 static final class Pack {final String id,title,author;Pack(String id,String title,String author){this.id=id;this.title=title;this.author=author;}}
 PackBrowser(GuiScreen parent){super(parent);}
 void layout(){if(!online)local=installed();scale=Math.max(.6f,Math.min(width/1000f,height/650f));logicalWidth=Math.round(width/scale);logicalHeight=Math.round(height/scale);pw=Math.min(930,logicalWidth-40);ph=Math.min(590,logicalHeight-40);left=(logicalWidth-pw)/2;top=(logicalHeight-ph)/2;
  button(left+16,top+16,60,28,"Back",this::close);button(left+100,top+16,90,28,"Installed",()->{online=false;page=0;initGui();}).selected=!online;button(left+200,top+16,90,28,"Browse",()->{online=true;page=0;search();}).selected=online;
  field(left+320,top+24,pw-440,23,query,"Search resource packs",s->query=s);button(left+pw-100,top+16,82,28,"Search",()->{page=0;if(online)search();else initGui();}).active=pending==null;
  button(left+pw-188,top+ph-40,80,26,"Previous",()->{page=Math.max(0,page-1);if(online)search();else initGui();}).active=pending==null&&page>0;
  button(left+pw-96,top+ph-40,80,26,"Next",()->{page++;if(online)search();else initGui();}).active=pending==null&&(online?packs.size()==rows():(page+1)*rows()<local.size());
  if(online){for(int i=0;i<packs.size();i++){final Pack p=packs.get(i);button(left+pw-118,top+70+i*rowHeight(),100,30,"Download",()->download(p)).active=pending==null;}}
  else{List<ResourcePackRepository.Entry> all=local;Set<ResourcePackRepository.Entry> selected=new HashSet<>(mc.getResourcePackRepository().getRepositoryEntries());int end=Math.min(all.size(),(page+1)*rows());for(int i=page*rows();i<end;i++){final ResourcePackRepository.Entry entry=all.get(i);button(left+pw-118,top+70+(i-page*rows())*rowHeight(),100,30,selected.contains(entry)?"Disable":"Enable",()->activate(entry)).active=entry.func_183027_f()==1;}}
 }
 int rowHeight(){return 62;}int rows(){return Math.max(1,(ph-130)/rowHeight());}
 List<ResourcePackRepository.Entry> installed(){mc.getResourcePackRepository().updateRepositoryEntriesAll();List<ResourcePackRepository.Entry> out=new ArrayList<>();for(ResourcePackRepository.Entry e:mc.getResourcePackRepository().getRepositoryEntriesAll())if(e.getResourcePackName().toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT)))out.add(e);return out;}
 void paint(float x,float y,float partial){Painter.round(left,top,pw,ph,28,SolidTheme.panel());Painter.text("RESOURCE PACKS",left+16,top-19,SolidTheme.text());if(online){for(int i=0;i<packs.size();i++){Pack p=packs.get(i);row(i,p.title,"By "+p.author+" · Minecraft 1.8.9");}if(packs.isEmpty())Painter.text(pending==null?"Enter a search or press Search to browse Modrinth.":"Loading…",left+24,top+94,SolidTheme.muted());}
  else{List<ResourcePackRepository.Entry> all=local;int end=Math.min(all.size(),(page+1)*rows());for(int i=page*rows();i<end;i++){ResourcePackRepository.Entry e=all.get(i);row(i-page*rows(),e.getResourcePackName(),e.func_183027_f()==1?e.getTexturePackDescription():"This pack format is not compatible with 1.8.9");}if(all.isEmpty())Painter.text("No installed packs match your search.",left+24,top+94,SolidTheme.muted());}Painter.clip(left+18,top+ph-38,pw-220,30);Painter.text(status,left+18,top+ph-32,SolidTheme.muted());Painter.unclip();
 }
 private void row(int i,String title,String subtitle){int y=top+66+i*rowHeight();Painter.round(left+16,y,pw-32,54,12,SolidTheme.card(0));Painter.clip(left+28,y+8,pw-170,44);Painter.text(title,left+28,y+9,SolidTheme.text());Painter.text(subtitle.replaceAll("§.",""),left+28,y+30,SolidTheme.muted());Painter.unclip();}
 void activate(ResourcePackRepository.Entry entry){ResourcePackRepository repo=mc.getResourcePackRepository();List<ResourcePackRepository.Entry> selected=new ArrayList<>(repo.getRepositoryEntries());if(!selected.remove(entry))selected.add(entry);repo.setRepositories(selected);mc.gameSettings.resourcePacks.clear();for(ResourcePackRepository.Entry e:selected)mc.gameSettings.resourcePacks.add(e.getResourcePackName());mc.gameSettings.saveOptions();mc.refreshResources();status="Resource packs updated";initGui();}
 void search(){if(pending!=null)return;final String q=query;final int offset=page*rows(),limit=rows();status="Loading compatible packs…";pending=worker.submit(()->{JsonObject json=json("search?query="+enc(q)+"&facets="+enc("[[\"project_type:resourcepack\"],[\"versions:1.8.9\"]]")+"&index=downloads&limit="+limit+"&offset="+offset).getAsJsonObject();List<Pack> result=new ArrayList<>();for(JsonElement v:json.getAsJsonArray("hits")){JsonObject p=v.getAsJsonObject();result.add(new Pack(p.get("project_id").getAsString(),p.get("title").getAsString(),p.get("author").getAsString()));}return result;});initGui();}
 void download(Pack pack){if(pending!=null)return;status="Downloading "+pack.title+"…";final Path directory=mc.getResourcePackRepository().getDirResourcepacks().toPath();pending=worker.submit(()->{JsonArray versions=json("project/"+pack.id+"/version?game_versions="+enc("[\"1.8.9\"]")).getAsJsonArray();if(versions.size()==0)throw new IOException("No compatible version available");JsonArray files=versions.get(0).getAsJsonObject().getAsJsonArray("files");JsonObject file=null;for(JsonElement v:files){JsonObject f=v.getAsJsonObject();if(f.get("filename").getAsString().toLowerCase(Locale.ROOT).endsWith(".zip")&&(file==null||f.get("primary").getAsBoolean()))file=f;}if(file==null)throw new IOException("No resource-pack ZIP available");
   String url=file.get("url").getAsString(),expected=file.getAsJsonObject("hashes").get("sha512").getAsString();Files.createDirectories(directory);Path tmp=Files.createTempFile(directory,"unbox-pack-",".part");try{String actual=downloadZip(new URL(url),tmp);if(!expected.equalsIgnoreCase(actual))throw new IOException("Download checksum mismatch");Path target=directory.resolve("modrinth-"+pack.id+"-"+actual.substring(0,16)+".zip");try(ZipFile zip=new ZipFile(tmp.toFile())){if(zip.getEntry("pack.mcmeta")==null||zip.getEntry("pack.mcmeta").getSize()>65536)throw new IOException("Missing or oversized pack metadata");try(Reader r=new InputStreamReader(zip.getInputStream(zip.getEntry("pack.mcmeta")),"UTF-8")){if(new JsonParser().parse(r).getAsJsonObject().getAsJsonObject("pack").get("pack_format").getAsInt()!=1)throw new IOException("Pack declares an incompatible format");}}Files.move(tmp,target,StandardCopyOption.REPLACE_EXISTING);}finally{Files.deleteIfExists(tmp);}return null;});initGui();}
 @Override boolean interceptKey(char c,int k){if(k==org.lwjgl.input.Keyboard.KEY_RETURN&&textFocused()){page=0;if(online)search();else initGui();return true;}return false;}
 @Override public void updateScreen(){if(pending==null||!pending.isDone())return;try{List<Pack> result=pending.get();if(result==null){status="Downloaded. Choose Enable to use your pack.";online=false;page=0;query="";}else{packs=result;status="Modrinth · Compatible with Minecraft 1.8.9";}}catch(Exception e){Throwable cause=e.getCause()==null?e:e.getCause();status="Could not complete request: "+cause.getMessage();}finally{pending=null;if(!closed)initGui();}}
 @Override public void onGuiClosed(){super.onGuiClosed();closed=true;if(pending!=null)pending.cancel(true);worker.shutdownNow();}
 static String enc(String s)throws UnsupportedEncodingException{return URLEncoder.encode(s,"UTF-8");}
 static JsonElement json(String path)throws Exception{return new JsonParser().parse(new String(bytes(new URL(API+path),8*1024*1024,"api.modrinth.com"),"UTF-8"));}
 static byte[] bytes(URL url,int max,String host)throws IOException{if(!url.getProtocol().equals("https")||!url.getHost().equals(host))throw new IOException("Unexpected download location");HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setConnectTimeout(10000);c.setReadTimeout(15000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","Unbox-unpvp/0.2.0 (local resource pack browser)");try{if(c.getResponseCode()!=200)throw new IOException("HTTP "+c.getResponseCode());if(c.getContentLengthLong()>max)throw new IOException("Download too large");try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buf=new byte[16384];int n;while((n=in.read(buf))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();if(out.size()+n>max)throw new IOException("Download too large");out.write(buf,0,n);}return out.toByteArray();}}finally{c.disconnect();}}
 static String downloadZip(URL url,Path file)throws Exception{if(!url.getProtocol().equals("https")||!url.getHost().equals("cdn.modrinth.com"))throw new IOException("Unexpected download location");HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setConnectTimeout(10000);c.setReadTimeout(15000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","Unbox-unpvp/0.2.0");MessageDigest digest=MessageDigest.getInstance("SHA-512");try{if(c.getResponseCode()!=200)throw new IOException("HTTP "+c.getResponseCode());long limit=256L*1024*1024;if(c.getContentLengthLong()>limit)throw new IOException("Download too large");try(InputStream in=c.getInputStream();OutputStream out=Files.newOutputStream(file)){byte[] buffer=new byte[65536];long count=0;int n;while((n=in.read(buffer))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();if((count+=n)>limit)throw new IOException("Download too large");digest.update(buffer,0,n);out.write(buffer,0,n);}}return hex(digest.digest());}finally{c.disconnect();}}
 static String hex(byte[] bytes){StringBuilder s=new StringBuilder();for(byte b:bytes)s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}
}
